const path = require('node:path')

const expandRefs = (schema, defs = {}) => {
  if (!schema || typeof schema !== 'object') return schema
  if (Array.isArray(schema)) {
    return schema.map((item) => expandRefs(item, defs))
  }

  const result = {}
  for (const [key, value] of Object.entries(schema)) {
    if (key === '$ref' && typeof value === 'string' && !value.startsWith('#')) {
      // Shorthand ref e.g. "uuid" -> "#/$defs/uuid"
      result['$ref'] = `#/$defs/${value}`
    } else if (key === '$defs' && typeof value === 'object') {
      result[key] = expandRefs(value, { ...defs, ...value })
    } else {
      result[key] = expandRefs(value, defs)
    }
  }

  return result
}

const compilePluginCode = (ontology, options = {}) => {
  const distDir = options.distDir || path.join(ontology.srcDir, '../dist')
  const events = []
  const projections = []
  const sideEffects = []

  // Context loading imports
  const contextInitLines = []
  for (const helper of ontology.helperFiles) {
    let relFromDist = path.relative(distDir, helper.fullPath).replace(/\\/g, '/')
    if (!relFromDist.startsWith('.')) {
      relFromDist = './' + relFromDist
    }
    contextInitLines.push(`  ${helper.key}: require(${JSON.stringify(relFromDist)}),`)
  }

  for (const [fullName, item] of ontology.resolvedMap.entries()) {
    const { key, version, resolved } = item
    const isEvent = fullName.includes('@') || resolved.$factory || resolved.$projections || resolved.$sideeffects

    if (!isEvent) continue

    // Normalize schema for Ajv validation
    const rawSchema = {
      $id: `${key}@${version}`,
      type: resolved.type || 'object',
      properties: resolved.properties || {},
      required: resolved.required || [],
      additionalProperties: resolved.additionalProperties !== undefined ? resolved.additionalProperties : false,
      $defs: resolved.$defs || {},
    }

    const cleanSchema = expandRefs(rawSchema, resolved.$defs || {})

    // Factory
    const factoryCode = typeof resolved.$factory === 'string'
      ? resolved.$factory.trim()
      : typeof resolved.$factory === 'boolean' && resolved.$factory
        ? `(payload) => ({ ...payload })`
        : `null`

    // Custom validator
    const customValidateCode = typeof resolved.$validate === 'string'
      ? resolved.$validate.trim()
      : `null`

    // Deduplication ID
    const dedupCode = typeof resolved.$deduplicationId === 'string'
      ? resolved.$deduplicationId.includes('=>')
        ? resolved.$deduplicationId.trim()
        : `(payload) => payload?.${resolved.$deduplicationId}`
      : `(payload) => payload?.id`

    // Partition Key
    const partCode = typeof resolved.$partitionKey === 'string'
      ? resolved.$partitionKey.includes('=>')
        ? resolved.$partitionKey.trim()
        : `(payload) => payload?.${resolved.$partitionKey}`
      : `null`

    events.push({
      type: key,
      version,
      schema: cleanSchema,
      factoryCode,
      customValidateCode,
      dedupCode,
      partCode,
      persisted: resolved.persisted !== undefined ? resolved.persisted : true,
      replicated: resolved.replicated !== undefined ? resolved.replicated : true,
    })

    if (resolved.$projections) {
      projections.push({
        type: key,
        version,
        code: resolved.$projections.trim(),
      })
    }

    if (resolved.$sideeffects) {
      sideEffects.push({
        type: key,
        version,
        code: resolved.$sideeffects.trim(),
      })
    }
  }

  // Generate JS code
  const code = `// Auto-generated by @sullux/event-ontology. DO NOT EDIT DIRECTLY.
const Ajv = require('ajv')

const ajv = new Ajv({ allErrors: true, useDefaults: true, allowUnionTypes: true })

const context = {
${contextInitLines.join('\n')}
}

const validateSchema = (schemaDef, data) => {
  let validate = ajv.getSchema(schemaDef.$id)
  if (!validate) {
    ajv.addSchema(schemaDef)
    validate = ajv.getSchema(schemaDef.$id)
  }

  const isValid = validate(data)
  if (!isValid) {
    const error = new Error('Validation Error: ' + JSON.stringify(validate.errors))
    error.errors = validate.errors
    throw error
  }

  return true
}

const definitions = [
${events.map((e) => {
  return `  {
    type: ${JSON.stringify(e.type)},
    version: ${JSON.stringify(e.version)},
    persisted: ${e.persisted},
    replicated: ${e.replicated},
    schema: ${JSON.stringify(e.schema, null, 2)},
    factory: ${e.factoryCode},
    customValidate: ${e.customValidateCode},
    deduplicationId: (payload, db, ctx) => (${e.dedupCode})(payload, db, ctx || context),
    partitionKey: (payload, db, ctx) => (${e.partCode})(payload, db, ctx || context),
    async validate(payload, db) {
      validateSchema(this.schema, payload)
      if (this.customValidate) {
        const errors = await this.customValidate(payload, db, context)
        if (Array.isArray(errors) && errors.length > 0) {
          const err = new Error('Custom Validation Error: ' + errors.join(', '))
          err.errors = errors
          throw err
        }
      }
      return true
    }
  },`
}).join('\n')}
]

const projections = [
${projections.map((p) => {
  return `  {
    type: ${JSON.stringify(p.type)},
    version: ${JSON.stringify(p.version)},
    handler: ${p.code}
  },`
}).join('\n')}
]

const sideEffects = [
${sideEffects.map((s) => {
  return `  {
    type: ${JSON.stringify(s.type)},
    version: ${JSON.stringify(s.version)},
    handler: ${s.code}
  },`
}).join('\n')}
]

module.exports = {
  name: 'compiled-ontology-plugin',
  version: '1.0.0',
  context,
  definitions,
  upcasters: {},
  projections,
  sideEffects,
}
`

  return code
}

module.exports = {
  expandRefs,
  compilePluginCode,
}
